/*!50001 DROP VIEW IF EXISTS `clean_new_view`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `clean_new_view` AS select `p`.`id` AS `post_id`,`p`.`content` AS `post_content`,`p`.`Title` AS `post_title`,`p`.`updated_at` AS `updated_at`,`p`.`CategoryID` AS `CategoryID`,`u`.`id` AS `user_id`,`u`.`email` AS `user_email`,`u`.`gender` AS `user_gender`,timestampdiff(YEAR,`u`.`birthday`,curdate()) AS `user_age`,group_concat(distinct `ui`.`action_type` order by `ui`.`action_type` ASC separator ',') AS `action_types`,coalesce(sum((case when (`ui`.`action_type` = 'view') then 1.0 when (`ui`.`action_type` = 'like') then 2.0 when (`ui`.`action_type` = 'comment') then 3.0 when (`ui`.`action_type` = 'share') then 5.0 when (`ui`.`action_type` = 'bookmark') then 4.0 when (`ui`.`action_type` = 'unbookmark') then -(2.0) when (`ui`.`action_type` = 'unlike') then -(1.0) when (`ui`.`action_type` = 'follow') then 0.0 when (`ui`.`action_type` = 'unfollow') then 0.0 else 0 end)),0) AS `total_interaction_score`,max(`ui`.`created_at`) AS `interaction_time`,`c`.`CategoryName` AS `category_name` from (((`posts` `p` left join `user_interactions` `ui` on((`p`.`id` = `ui`.`post_id`))) left join `users` `u` on((`ui`.`user_id` = `u`.`id`))) join `category` `c` on((`p`.`CategoryID` = `c`.`CategoryID`))) where ((`p`.`status` = 'active') and (`c`.`CategoryName` in ('Electronics & Gadgets','Furniture','Outdoor Gear','Beauty Products','Accessories'))) group by `p`.`id`,`u`.`id`,`p`.`content`,`p`.`Title`,`p`.`updated_at`,`p`.`CategoryID`,`u`.`email`,`u`.`gender`,timestampdiff(YEAR,`u`.`birthday`,curdate()),`c`.`CategoryName` */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;

