-- Final view structure for view `collaborativeview`
--

/*!50001 DROP VIEW IF EXISTS `collaborativeview`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `collaborativeview` AS select `p`.`id` AS `post_id`,`ua`.`user_id` AS `user_id`,(case when (`c`.`CategoryName` = 'Electronics & Gadgets') then `ua`.`Score` else 0.0 end) AS `Electronics_Gadgets`,(case when (`c`.`CategoryName` = 'Furniture') then `ua`.`Score` else 0.0 end) AS `Furniture`,(case when (`c`.`CategoryName` = 'Outdoor Gear') then `ua`.`Score` else 0.0 end) AS `Outdoor_Gear`,(case when (`c`.`CategoryName` = 'Beauty Products') then `ua`.`Score` else 0.0 end) AS `Beauty_Products`,(case when (`c`.`CategoryName` = 'Accessories') then `ua`.`Score` else 0.0 end) AS `Accessories`,(case when (`u`.`gender` = 'Male') then 1 else 0 end) AS `Male`,(case when (`u`.`gender` = 'Female') then 1 else 0 end) AS `Female`,(case when (`u`.`gender` = 'Other') then 1 else 0 end) AS `Other`,`u`.`age` AS `Age` from ((((select `ui`.`user_id` AS `user_id`,`ui`.`post_id` AS `post_id`,sum((case `ui`.`action_type` when 'view' then 1.0 when 'like' then 2.0 when 'unlike' then -(1.0) when 'comment' then 3.0 when 'bookmark' then 4.0 when 'unbookmark' then -(2.0) when 'share' then 5.0 else 0.0 end)) AS `Score` from `user_interactions` `ui` where (`ui`.`action_type` in ('view','like','unlike','comment','bookmark','unbookmark','share')) group by `ui`.`user_id`,`ui`.`post_id`) `ua` join `posts` `p` on((`p`.`id` = `ua`.`post_id`))) join `category` `c` on((`p`.`CategoryID` = `c`.`CategoryID`))) join `users` `u` on((`u`.`id` = `ua`.`user_id`))) where ((`p`.`status` = 'active') and (`c`.`CategoryName` in ('Electronics & Gadgets','Furniture','Outdoor Gear','Beauty Products','Accessories'))) */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;

