-- Final view structure for view `contentbasedview`
--

/*!50001 DROP VIEW IF EXISTS `contentbasedview`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_0900_ai_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `contentbasedview` AS select `p`.`id` AS `post_id`,max(`p`.`user_id`) AS `owner_id`,coalesce(max(`fa`.`Engagement`),0) AS `PostEngagement`,max(`p`.`content`) AS `Content`,coalesce(group_concat(distinct `cm`.`comment_text` order by `cm`.`id` ASC separator '; '),'') AS `Comments`,max((case when (`u`.`gender` = 'Male') then 1 else 0 end)) AS `Male`,max((case when (`u`.`gender` = 'Female') then 1 else 0 end)) AS `Female`,max((case when (`u`.`gender` = 'Other') then 1 else 0 end)) AS `Other`,max(`u`.`age`) AS `Age`,max((case when (`c`.`CategoryName` = 'Electronics & Gadgets') then 1 else 0 end)) AS `Electronics_Gadgets`,max((case when (`c`.`CategoryName` = 'Furniture') then 1 else 0 end)) AS `Furniture`,max((case when (`c`.`CategoryName` = 'Outdoor Gear') then 1 else 0 end)) AS `Outdoor_Gear`,max((case when (`c`.`CategoryName` = 'Beauty Products') then 1 else 0 end)) AS `Beauty_Products`,max((case when (`c`.`CategoryName` = 'Accessories') then 1 else 0 end)) AS `Accessories` from ((((`posts` `p` join `users` `u` on((`p`.`user_id` = `u`.`id`))) join `category` `c` on((`p`.`CategoryID` = `c`.`CategoryID`))) left join (select `ui`.`post_id` AS `post_id`,sum((case `ui`.`action_type` when 'view' then 1.0 when 'like' then 2.0 when 'unlike' then -(1.0) when 'comment' then 3.0 when 'bookmark' then 4.0 when 'unbookmark' then -(2.0) when 'share' then 5.0 else 0.0 end)) AS `Engagement` from `user_interactions` `ui` where (`ui`.`action_type` in ('view','like','unlike','comment','bookmark','unbookmark','share')) group by `ui`.`post_id`) `fa` on((`p`.`id` = `fa`.`post_id`))) left join `comments` `cm` on((`p`.`id` = `cm`.`post_id`))) where ((`p`.`status` = 'active') and (`c`.`CategoryName` in ('Electronics & Gadgets','Furniture','Outdoor Gear','Beauty Products','Accessories'))) group by `p`.`id` */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;
